COPY public.sql (id, name, data_source, geo_level, body) FROM stdin;
2	Land Use	gis	municipality	select\n  geoid,\n  ROUND(SUM(acres), 2) as total_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Agriculture' THEN acres ELSE 0 END), 2) AS agriculture_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Commercial' THEN acres ELSE 0 END), 2) AS commercial_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Industrial' THEN acres ELSE 0 END), 2) AS industrial_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Institutional' THEN acres ELSE 0 END), 2) AS institutional_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Military' THEN acres ELSE 0 END), 2) AS military_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Mining' THEN acres ELSE 0 END), 2) AS mining_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Recreation' THEN acres ELSE 0 END), 2) AS recreation_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Residential' THEN acres ELSE 0 END), 2) AS residential_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Transportation' THEN acres ELSE 0 END), 2) AS transportation_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Undeveloped' THEN acres ELSE 0 END), 2) AS undeveloped_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Utility' THEN acres ELSE 0 END), 2) AS utility_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Water' THEN acres ELSE 0 END), 2) AS water_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Wooded' THEN acres ELSE 0 END), 2) AS wooded_acres\nFROM planning.dvrpc_landuse_2023\nGROUP BY geoid;\n
12	Population & Employment Forecasts	gis	municipality	SELECT geoid, pop20, pop25, pop30, pop35, pop40, pop45, pop50, emp20, emp25, emp30, emp35, emp40, emp45, emp50, popabs50, poppct50, empabs50, emppct50\nFROM demographics.forecast_2050_mcd_table_v2;
13	Trails	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, t.shape))) / 1609.34)\n    FROM transportation.all_trails t\n    WHERE ST_Intersects(m.shape, t.shape)\n  ), 0) AS existing_trail_mi,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, ct.shape))) / 1609.34)\n    FROM transportation.circuittrails ct\n    WHERE ST_Intersects(m.shape, ct.shape) and ct.circuit != 'Existing'\n  ), 0) AS planned_trail_mi\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
14	Freight	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, fr.shape))) / 1609.34)\n    FROM freight.freight_rail fr\n    WHERE ST_Intersects(m.shape, fr.shape)\n  ), 0) AS freight_rail_mi,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, hw.shape))) / 1609.34)\n    FROM freight.highways hw\n    WHERE ST_Intersects(m.shape, hw.shape)\n  ), 0) AS highway_mi,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM freight.freight_centers fc\n    WHERE ST_Area(ST_Intersection(m.shape, fc.shape)) > 0\n  ), 0) AS unique_freight_centers\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
15	TIP	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.patip_fy2025_2028_line tip\n    WHERE ST_Intersects(m.shape, tip.shape)\n  ), 0) AS fy25_pa_lines,\n    COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtip_fy2026_2029_line tip\n    WHERE ST_Intersects(m.shape, tip.shape)\n  ), 0) AS fy26_nj_lines,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.patip_fy2025_2028_point tip\n    WHERE ST_Intersects(m.shape, tip.shape)\n  ), 0) AS fy25_pa_points,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtip_fy2026_2029_point tip\n    WHERE ST_Intersects(m.shape, tip.shape)\n  ), 0) AS fy26_nj_points\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
5	Freight	gis	county	SELECT\n  c.fips as geoid,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, fr.shape))) / 1609.34)\n    FROM freight.freight_rail fr\n    WHERE ST_Intersects(c.shape, fr.shape)\n  ), 0) AS freight_rail_mi,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, hw.shape))) / 1609.34)\n    FROM freight.highways hw\n    WHERE ST_Intersects(c.shape, hw.shape)\n  ), 0) AS highway_mi,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM freight.freight_centers fc\n    WHERE ST_Area(ST_Intersection(c.shape, fc.shape)) > 0\n  ), 0) AS unique_freight_centers\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
8	SEPTA Bus	gis	county	SELECT\n  c.fips as geoid,\nCOALESCE((\n    SELECT COUNT(*)\n    FROM transportation.septa_transitstops sp\n    WHERE ST_Intersects(c.shape, ST_transform(sp.shape, 26918))\n  ), 0) AS septa_bus_stops,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, ST_transform(sp.shape, 26918)))) / 1609.34)\n    FROM transportation.septa_transitroutes sp\n    WHERE ST_Intersects(c.shape, ST_transform(sp.shape, 26918))\n  ), 0) AS septa_bus_routes_mi\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
6	Passenger Rail	gis	county	SELECT\n  c.fips as geoid,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.passengerrailstations prs\n    WHERE ST_Intersects(c.shape, prs.shape)\n  ), 0) AS passenger_rail_stations,\n\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, pr.shape))) / 1609.34)\n    FROM transportation.passengerrail pr\n    WHERE ST_Intersects(c.shape, pr.shape)\n  ), 0) AS passenger_rail_mi\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
9	NJT Bus	gis	county	SELECT\n  c.fips as geoid,  \nCOALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtransit_transitstops njt\n    WHERE ST_Intersects(c.shape, ST_transform(njt.shape, 26918))\n  ), 0) AS njt_bus_stops,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, ST_transform(njt.shape, 26918)))) / 1609.34)\n    FROM transportation.njtransit_transitroutes njt\n    WHERE ST_Intersects(c.shape, ST_transform(njt.shape, 26918))\n  ), 0) AS njt_bus_routes_mi\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
10	Open Space	gis	county	SELECT\n  c.fips as geoid,\nCOALESCE((\n    SELECT (SUM(ST_Area(ST_Intersection(c.shape, os.shape))) / 1609.34)\n    FROM planning.dvrpc_protectedopenspace os\n    WHERE ST_Intersects(c.shape, os.shape)\n  ), 0) AS protected_open_space_sq_mi\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
11	Population & Employment Forecasts	gis	county	SELECT fips as geoid, pop20, pop25, pop30, pop35, pop40, pop45, pop50, emp20, emp25, emp30, emp35, emp40, emp45, emp50, popabs50, poppct50, empabs50, emppct50\nFROM demographics.forecast_2050_county_table_v2;
16	SEPTA Bus	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.septa_transitstops sp\n    WHERE ST_Intersects(m.shape, ST_transform(sp.shape, 26918))\n  ), 0) AS septa_bus_stops,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, ST_transform(sp.shape, 26918)))) / 1609.34)\n    FROM transportation.septa_transitroutes sp\n    WHERE ST_Intersects(m.shape, ST_transform(sp.shape, 26918))\n  ), 0) AS septa_bus_routes_mi\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
17	NJT Bus	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtransit_transitstops njt\n    WHERE ST_Intersects(m.shape, ST_transform(njt.shape, 26918))\n  ), 0) AS njt_bus_stops,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, ST_transform(njt.shape, 26918)))) / 1609.34)\n    FROM transportation.njtransit_transitroutes njt\n    WHERE ST_Intersects(m.shape, ST_transform(njt.shape, 26918))\n  ), 0) AS njt_bus_routes_mi\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
18	Passenger Rail	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.passengerrailstations prs\n    WHERE ST_Intersects(m.shape, prs.shape)\n  ), 0) AS passenger_rail_stations,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(m.shape, pr.shape))) / 1609.34)\n    FROM transportation.passengerrail pr\n    WHERE ST_Intersects(m.shape, pr.shape)\n  ), 0) AS passenger_rail_mi\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
19	Open Space	gis	municipality	SELECT\n  m.geoid,\n  COALESCE((\n    SELECT (SUM(ST_Area(ST_Intersection(m.shape, os.shape))) / 1609.34)\n    FROM planning.dvrpc_protectedopenspace os\n    WHERE ST_Intersects(m.shape, os.shape)\n  ), 0) AS protected_open_space_sq_mi\nFROM\n  boundaries.municipalboundaries m\nwhere m.dvrpc_reg = 'Yes';
24	Electric Vehicles	ckan	municipality	SELECT geoid, bev, phev, total_ev, other_fuel, total_ldv, pct_ev_ldv, change_ev, pct_change_ev, change_ldv, pct_change_ldv FROM "31691dde-5bd5-4570-ab9f-79c498f72497" WHERE YEAR = (SELECT MAX(YEAR) FROM "31691dde-5bd5-4570-ab9f-79c498f72497") AND geoid IS NOT NULL
20	Bridge Conditions	ckan	county	SELECT\n    county_id as geoid,\n    SUM(CASE WHEN nhs_type = 'All' AND condition = 'Good' THEN count_bridges ELSE 0 END) AS bridge_all_good,\n    SUM(CASE WHEN nhs_type = 'All' AND condition = 'Fair' THEN count_bridges ELSE 0 END) AS bridge_all_fair,\n    SUM(CASE WHEN nhs_type = 'All' AND condition = 'Poor' THEN count_bridges ELSE 0 END) AS bridge_all_poor,\n    SUM(CASE WHEN nhs_type = 'NHS' AND condition = 'Good' THEN count_bridges ELSE 0 END) AS bridge_nhs_good,\n    SUM(CASE WHEN nhs_type = 'NHS' AND condition = 'Fair' THEN count_bridges ELSE 0 END) AS bridge_nhs_fair,\n    SUM(CASE WHEN nhs_type = 'NHS' AND condition = 'Poor' THEN count_bridges ELSE 0 END) AS bridge_nhs_poor,\n    SUM(CASE WHEN nhs_type = 'Non-NHS' AND condition = 'Good' THEN count_bridges ELSE 0 END) AS bridge_nonnhs_good,\n    SUM(CASE WHEN nhs_type = 'Non-NHS' AND condition = 'Fair' THEN count_bridges ELSE 0 END) AS bridge_nonnhs_fair,\n    SUM(CASE WHEN nhs_type = 'Non-NHS' AND condition = 'Poor' THEN count_bridges ELSE 0 END) AS bridge_nonnhs_poor\nFROM\n    "6b065499-c75d-48bd-a3c1-6c7bcf030efa" as t\nWHERE\n    year = (SELECT MAX(year) FROM "6b065499-c75d-48bd-a3c1-6c7bcf030efa")\nGROUP BY\n    county_id
21	Electric Vehicles	ckan	county	SELECT geoid, bev, phev, total_ev, other_fuel, total_ldv, pct_ev_ldv, change_ev, pct_change_ev, change_ldv, pct_change_ldv FROM "97af7cbb-11b9-4f98-9d71-b2a6e5bfb994" WHERE YEAR = (SELECT MAX(YEAR) FROM "97af7cbb-11b9-4f98-9d71-b2a6e5bfb994")
22	Housing Affordability	ckan	county	SELECT county_id as geoid, percent_cost_burdened from "4a3105ac-cc2f-4ba2-8b25-68ae4c1e311c" WHERE year = (SELECT MAX(year) FROM "4a3105ac-cc2f-4ba2-8b25-68ae4c1e311c")
7	TIP	gis	county	SELECT\n  c.fips as geoid,  \nCOALESCE((\n    SELECT COUNT(*)\n    FROM transportation.patip_fy2025_2028_line tip\n    WHERE ST_Intersects(c.shape, tip.shape)\n  ), 0) AS fy25_pa_lines,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtip_fy2026_2029_line tip\n    WHERE ST_Intersects(c.shape, tip.shape)\n  ), 0) AS fy26_nj_lines,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.patip_fy2025_2028_point tip\n    WHERE ST_Intersects(c.shape, tip.shape)\n  ), 0) AS fy25_pa_points,\n  COALESCE((\n    SELECT COUNT(*)\n    FROM transportation.njtip_fy2026_2029_point tip\n    WHERE ST_Intersects(c.shape, tip.shape)\n  ), 0) AS fy26_nj_points\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
23	Pavement Conditions	ckan	county	SELECT\n    county_id as geoid,\n    SUM(CASE WHEN metric = 'PM2' AND pavement_condition = 'Good' THEN miles ELSE 0 END) AS road_pm2_good,\n    SUM(CASE WHEN metric = 'PM2' AND pavement_condition = 'Fair' THEN miles ELSE 0 END) AS road_pm2_fair,\n    SUM(CASE WHEN metric = 'PM2' AND pavement_condition = 'Poor' THEN miles ELSE 0 END) AS road_pm2_poor,\n    SUM(CASE WHEN metric = 'IRI' AND pavement_condition = 'Good' THEN miles ELSE 0 END) AS road_iri_good,\n    SUM(CASE WHEN metric = 'IRI' AND pavement_condition = 'Fair' THEN miles ELSE 0 END) AS road_iri_fair,\n    SUM(CASE WHEN metric = 'IRI' AND pavement_condition = 'Poor' THEN miles ELSE 0 END) AS road_iri_poor,\n    SUM(CASE WHEN metric = 'DOT Pavement Index' AND pavement_condition = 'Good' THEN miles ELSE 0 END) AS road_dot_index_good,\n    SUM(CASE WHEN metric = 'DOT Pavement Index' AND pavement_condition = 'Fair' THEN miles ELSE 0 END) AS road_dot_index_fair,\n    SUM(CASE WHEN metric = 'DOT Pavement Index' AND pavement_condition = 'Poor' THEN miles ELSE 0 END) AS road_dot_index_poor\nFROM\n    "4e632db0-9830-4f7b-9ff3-072353ea9e6a"\nWHERE\n    year = (SELECT MAX(year) FROM "4e632db0-9830-4f7b-9ff3-072353ea9e6a") AND road_type = 'Total'\nGROUP BY\n    county_id
3	Trails	gis	county	SELECT\n  c.fips as geoid,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, t.shape))) / 1609.34)\n    FROM transportation.all_trails t\n    WHERE ST_Intersects(c.shape, t.shape)\n  ), 0) AS existing_trail_mi2,\n  COALESCE((\n    SELECT (SUM(ST_Length(ST_Intersection(c.shape, ct.shape))) / 1609.34)\n    FROM transportation.circuittrails ct\n    WHERE ST_Intersects(c.shape, ct.shape) and ct.circuit != 'Existing'\n  ), 0) AS planned_trail_mi\nFROM\n  boundaries.countyboundaries c\nwhere c.dvrpc_reg = 'Yes';
1	Land Use	gis	county	select\n  SUBSTRING(geoid, 0, 6) as geoid,\n  ROUND(SUM(acres), 2) as total_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Agriculture' THEN acres ELSE 0 END), 2) AS agriculture_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Commercial' THEN acres ELSE 0 END), 2) AS commercial_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Industrial' THEN acres ELSE 0 END), 2) AS industrial_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Institutional' THEN acres ELSE 0 END), 2) AS institutional_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Military' THEN acres ELSE 0 END), 2) AS military_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Mining' THEN acres ELSE 0 END), 2) AS mining_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Recreation' THEN acres ELSE 0 END), 2) AS recreation_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Residential' THEN acres ELSE 0 END), 2) AS residential_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Transportation' THEN acres ELSE 0 END), 2) AS transportation_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Undeveloped' THEN acres ELSE 0 END), 2) AS undeveloped_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Utility' THEN acres ELSE 0 END), 2) AS utility_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Water' THEN acres ELSE 0 END), 2) AS water_acres,\n  ROUND(SUM(CASE WHEN lu23catn = 'Wooded' THEN acres ELSE 0 END), 2) AS wooded_acres\nFROM planning.dvrpc_landuse_2023\nGROUP BY SUBSTRING(geoid, 0, 6);\n
\.
